content:
:root {
  --color-bg: #f4f6f9;
  --color-surface: #ffffff;
  --color-surface-hover: #f8fafc;
  --color-border: #e2e8f0;
  --color-border-focus: #3b82f6;
  --color-text-primary: #1e293b;
  --color-text-secondary: #64748b;
  --color-text-muted: #94a3b8;
  --color-primary: #3b82f6;
  --color-primary-hover: #2563eb;
  --color-danger: #ef4444;
  --color-danger-hover: #dc2626;
  --color-danger-bg: #fee2e2;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-full: 9999px;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.08), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.04);
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --transition: all 0.2s ease-in-out;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: var(--color-bg);
  color: var(--color-text-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* アプリ全体コンテナ */
.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px 16px 48px;
}

/* ヘッダー */
.app-header {
  margin-bottom: 24px;
  text-align: center;
}

.app-title {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--color-text-primary);
  margin-bottom: 6px;
  letter-spacing: -0.02em;
}

.app-subtitle {
  font-size: 0.925rem;
  color: var(--color-text-secondary);
}

/* 合計金額バナー */
.total-banner {
  background: linear-gradient(135deg, #2563eb, #1d4ed8);
  border-radius: var(--radius-lg);
  padding: 20px 28px;
  margin-bottom: 28px;
  color: #ffffff;
  display: flex;
  justify-content: space-between;
  align-items: center;
  box-shadow: var(--shadow-md);
  flex-wrap: wrap;
  gap: 12px;
}

.total-label {
  font-size: 1rem;
  font-weight: 500;
  opacity: 0.9;
}

.total-value {
  font-size: 2rem;
  font-weight: 800;
  letter-spacing: -0.01em;
}

/* ダッシュボードグリッド（グラフとリストを横並び） */
.dashboard-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
  margin-bottom: 28px;
}

/* チャートカード */
.chart-card {
  background-color: var(--color-surface);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--color-border);
  display: flex;
  flex-direction: column;
  align-items: center;
  position: relative;
}

.chart-wrapper {
  width: 100%;
  height: 320px;
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
}

/* チャートツールチップ */
.chart-tooltip {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 8px 12px;
  box-shadow: var(--shadow-md);
  pointer-events: none;
}

.chart-tooltip-title {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-text-primary);
  margin-bottom: 2px;
}

.chart-tooltip-amount {
  font-size: 1rem;
  font-weight: 700;
  color: var(--color-primary);
}

.chart-tooltip-note {
  font-size: 0.75rem;
  color: var(--color-text-secondary);
  margin-top: 2px;
}

/* 選択された項目の情報表示ボックス */
.selected-info-box {
  width: 100%;
  margin-top: 16px;
  padding: 16px;
  background-color: var(--color-bg);
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  text-align: center;
  transition: var(--transition);
}

.selected-info-title {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--color-text-primary);
  margin-bottom: 4px;
}

.selected-info-amount {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-primary);
  margin-bottom: 4px;
}

.selected-info-percent {
  display: inline-block;
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--color-text-secondary);
  background-color: var(--color-surface);
  padding: 2px 10px;
  border-radius: var(--radius-full);
  border: 1px solid var(--color-border);
}

.selected-info-note {
  font-size: 0.825rem;
  color: var(--color-text-muted);
  margin-top: 6px;
}

/* 支出リストカード */
.list-card {
  background-color: var(--color-surface);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--color-border);
  display: flex;
  flex-direction: column;
}

.list-header {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--color-text-primary);
  margin-bottom: 16px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--color-border);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.list-count {
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--color-text-secondary);
  background-color: var(--color-bg);
  padding: 2px 10px;
  border-radius: var(--radius-full);
  border: 1px solid var(--color-border);
}

.expense-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 440px;
  overflow-y: auto;
  padding-right: 4px;
  scrollbar-width: thin;
  scrollbar-color: var(--color-text-muted) var(--color-bg);
}

/* カスタムスクロールバー */
.expense-list::-webkit-scrollbar {
  width: 6px;
}

.expense-list::-webkit-scrollbar-track {
  background: var(--color-bg);
  border-radius: var(--radius-full);
}

.expense-list::-webkit-scrollbar-thumb {
  background: var(--color-text-muted);
  border-radius: var(--radius-full);
}

.expense-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 14px;
  background-color: var(--color-surface);
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  cursor: pointer;
  transition: var(--transition);
}

.expense-item:hover {
  background-color: var(--color-surface-hover);
  border-color: #cbd5e1;
  transform: translateY(-1px);
}

.expense-item.active {
  background-color: #eff6ff;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 1px var(--color-primary);
}

.expense-color-dot {
  width: 12px;
  height: 12px;
  border-radius: var(--radius-full);
  margin-right: 12px;
  flex-shrink: 0;
}

.expense-info {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  margin-right: 12px;
}

.expense-category {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--color-text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.expense-note {
  font-size: 0.8rem;
  color: var(--color-text-secondary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.expense-amount-group {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  margin-right: 12px;
}

.expense-amount {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--color-text-primary);
}

.expense-percent {
  font-size: 0.75rem;
  color: var(--color-text-muted);
}

.btn-delete {
  background-color: transparent;
  color: var(--color-text-muted);
  border: none;
  width: 28px;
  height: 28px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: var(--transition);
  font-size: 1.1rem;
}

.btn-delete:hover {
  background-color: var(--color-danger-bg);
  color: var(--color-danger);
}

.btn-delete:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--color-danger);
}

.empty-message {
  text-align: center;
  color: var(--color-text-muted);
  padding: 32px 16px;
  font-size: 0.9rem;
}

/* 登録フォームカード */
.form-card {
  background-color: var(--color-surface);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--color-border);
}

.form-title {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--color-text-primary);
  margin-bottom: 16px;
  padding-bottom: 0;
  border-bottom: none;
}

.form-card .list-header {
  margin-bottom: 16px;
  padding-bottom: 0;
  border-bottom: none;
}

.expense-form {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.form-row {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.form-label {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--color-text-secondary);
}

.form-input,
.form-select {
  height: 42px;
  padding: 0 12px;
  font-size: 0.95rem;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  background-color: var(--color-surface);
  color: var(--color-text-primary);
  outline: none;
  transition: var(--transition);
  font-family: inherit;
}

.form-input:focus,
.form-select:focus {
  border-color: var(--color-border-focus);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);
}

.form-input::placeholder {
  color: var(--color-text-muted);
}

.btn-add {
  height: 42px;
  background-color: var(--color-primary);
  color: #ffffff;
  font-size: 0.95rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: var(--transition);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  margin-top: 8px;
  padding: 0 24px;
  align-self: flex-end;
}

.btn-add:hover {
  background-color: var(--color-primary-hover);
  box-shadow: var(--shadow-md);
  transform: translateY(-1px);
}

.btn-add:active {
  transform: translateY(0);
}

.btn-add:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.4);
}

/* レスポンシブ対応 */
@media (max-width: 900px) {
  .dashboard-grid {
    grid-template-columns: 1fr;
  }

  .chart-wrapper {
    height: 280px;
  }
}

@media (max-width: 600px) {
  .app-container {
    padding: 16px 12px 36px;
  }

  .app-title {
    font-size: 1.4rem;
  }

  .total-banner {
    padding: 16px 20px;
  }

  .total-value {
    font-size: 1.6rem;
  }

  .chart-card,
  .list-card,
  .form-card {
    padding: 16px;
  }

  .form-row {
    grid-template-columns: 1fr;
  }

  .btn-add {
    width: 100%;
  }

  .expense-item {
    padding: 10px 12px;
  }

  .expense-amount {
    font-size: 0.9rem;
  }
}

export interface ExpenseItem {
  id: string;
  category: string;
  amount: number;
  color: string;
  note: string;
}

export interface PresetCategory {
  category: string;
  defaultColor: string;
}

export interface ExpensePieChartProps {
  items: ExpenseItem[];
  selectedId: string | null;
  onSelect: (id: string | null) => void;
}

export interface ExpenseListProps {
  items: ExpenseItem[];
  selectedId: string | null;
  onSelect: (id: string | null) => void;
  onDelete: (id: string) => void;
  totalAmount: number;
}

import { FC, useMemo } from 'react';
import { ResponsiveContainer, PieChart, Pie, Cell, Tooltip } from 'recharts';
import { ExpensePieChartProps, ExpenseItem } from '../types';

interface CustomTooltipProps {
  active?: boolean;
  payload?: Array<{
    payload: ExpenseItem;
  }>;
}

interface PieClickData {
  id?: string;
  payload?: ExpenseItem;
  [key: string]: unknown;
}

const CustomTooltip: FC<CustomTooltipProps> = ({ active, payload }) => {
  if (active && payload && payload.length > 0) {
    const data = payload[0].payload;
    return (
      <div className="chart-tooltip">
        <p className="chart-tooltip-title">{data.category}</p>
        <p className="chart-tooltip-amount">¥{data.amount.toLocaleString()}</p>
        {data.note && (
          <p className="chart-tooltip-note">{data.note}</p>
        )}
      </div>
    );
  }
  return null;
};

const ExpensePieChart: FC<ExpensePieChartProps> = ({
  items = [],
  selectedId,
  onSelect,
}) => {
  const totalAmount = useMemo(() => {
    return items.reduce((sum, item) => sum + item.amount, 0);
  }, [items]);

  const selectedItem = useMemo(() => {
    return items.find((item) => item.id === selectedId) || null;
  }, [items, selectedId]);

  const selectedPercentage = useMemo(() => {
    if (!selectedItem || totalAmount === 0) return 0;
    return Math.round((selectedItem.amount / totalAmount) * 1000) / 10;
  }, [selectedItem, totalAmount]);

  const handlePieClick = (entry?: PieClickData | ExpenseItem | null) => {
    if (!entry) return;
    const targetId =
      'id' in entry && typeof entry.id === 'string'
        ? entry.id
        : entry.payload?.id;

    if (!targetId) return;

    if (selectedId === targetId) {
      onSelect?.(null);
    } else {
      onSelect?.(targetId);
    }
  };

  return (
    <div className="chart-card">
      <div className="chart-wrapper">
        {items.length === 0 ? (
          <div className="empty-message">支出データがありません</div>
        ) : (
          <ResponsiveContainer width="100%" height="100%">
            <PieChart>
              <Pie
                data={items}
                dataKey="amount"
                nameKey="category"
                cx="50%"
                cy="50%"
                innerRadius={65}
                outerRadius={105}
                paddingAngle={3}
                onClick={(entry) => handlePieClick(entry)}
                cursor="pointer"
              >
                {items.map((entry) => {
                  const isSelected = entry.id === selectedId;
                  return (
                    <Cell
                      key={`cell-${entry.id}`}
                      fill={entry.color}
                      stroke={isSelected ? '#1e293b' : '#ffffff'}
                      strokeWidth={isSelected ? 3 : 1}
                      style={{
                        outline: 'none',
                        transition: 'transform 0.2s ease',
                        transform: isSelected ? 'scale(1.04)' : 'scale(1)',
                        transformOrigin: 'center center',
                      }}
                    />
                  );
                })}
              </Pie>
              <Tooltip content={<CustomTooltip />} />
            </PieChart>
          </ResponsiveContainer>
        )}
      </div>

      {items.length === 0 ? (
        <div className="selected-info-box">
          <div className="selected-info-title">データが登録されていません</div>
          <div className="selected-info-note">
            下のフォームから支出を登録してください
          </div>
        </div>
      ) : selectedItem ? (
        <div className="selected-info-box">
          <div className="selected-info-title">{selectedItem.category}</div>
          <div className="selected-info-amount">
            ¥{selectedItem.amount.toLocaleString()}
          </div>
          <div>
            <span className="selected-info-percent">
              {selectedPercentage}% (全体比)
            </span>
          </div>
          {selectedItem.note && (
            <div className="selected-info-note">{selectedItem.note}</div>
          )}
        </div>
      ) : (
        <div className="selected-info-box">
          <div className="selected-info-title">項目未選択</div>
          <div className="selected-info-note">
            グラフや一覧の項目をクリックすると詳細が表示されます
          </div>
        </div>
      )}
    </div>
  );
};

export default ExpensePieChart;

import { FC, MouseEvent, KeyboardEvent } from 'react';
import { ExpenseListProps, ExpenseItem } from '../types';

const ExpenseList: FC<ExpenseListProps> = ({
  items = [],
  selectedId,
  onSelect,
  onDelete,
  totalAmount,
}) => {
  const handleDeleteClick = (e: MouseEvent<HTMLButtonElement>, item: ExpenseItem) => {
    e.stopPropagation();
    if (window.confirm(`「${item.category}」の支出を削除してもよろしいですか？`)) {
      onDelete?.(item.id);
    }
  };

  const handleKeyDown = (e: KeyboardEvent<HTMLLIElement>, id: string) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      onSelect?.(id);
    }
  };

  return (
    <div className="list-card">
      <div className="list-header">
        <span>支出項目一覧</span>
        <span className="list-count">
          {items.length} 件
        </span>
      </div>

      {items.length === 0 ? (
        <div className="empty-message">登録された支出項目はありません</div>
      ) : (
        <ul className="expense-list">
          {items.map((item) => {
            const isSelected = item.id === selectedId;
            const percent =
              totalAmount > 0
                ? Math.round((item.amount / totalAmount) * 1000) / 10
                : 0;

            return (
              <li
                key={item.id}
                tabIndex={0}
                role="button"
                aria-pressed={isSelected}
                className={isSelected ? 'expense-item active' : 'expense-item'}
                onClick={() => onSelect?.(item.id)}
                onKeyDown={(e) => handleKeyDown(e, item.id)}
              >
                <div
                  className="expense-color-dot"
                  style={{ backgroundColor: item.color }}
                />
                <div className="expense-info">
                  <span className="expense-category">{item.category}</span>
                  {item.note && (
                    <span className="expense-note">{item.note}</span>
                  )}
                </div>
                <div className="expense-amount-group">
                  <span className="expense-amount">
                    ¥{item.amount.toLocaleString()}
                  </span>
                  <span className="expense-percent">{percent}%</span>
                </div>
                <button
                  type="button"
                  className="btn-delete"
                  title="削除"
                  onClick={(e) => handleDeleteClick(e, item)}
                  aria-label={`${item.category}を削除`}
                >
                  ×
                </button>
              </li>
            );
          })}
        </ul>
      )}
    </div>
  );
};

export default ExpenseList;

