  };

  const handleDeleteItem = (id: string) => {
    setItems((prev) => prev.filter((item) => item.id !== id));
    if (selectedId === id) {
      setSelectedId(null);
    }
  };

  const handleAddExpense = (e: FormEvent) => {
    e.preventDefault();
    const parsedAmount = parseInt(amountInput, 10);
    if (isNaN(parsedAmount) || parsedAmount <= 0) {
      setErrorMessage('1円以上の有効な金額を入力してください。');
      return;
    }

    setErrorMessage('');

    const matchedPreset = PRESET_CATEGORIES.find((p) => p.category === category);
    const color = matchedPreset ? matchedPreset.defaultColor : '#3b82f6';

    const newItem: ExpenseItem = {
      id: generateUniqueId(),
      category,
      amount: parsedAmount,
      color,
      note: note.trim(),
    };

    setItems((prev) => [newItem, ...prev]);
    setSelectedId(newItem.id);
    setAmountInput('');
    setNote('');
  };

  return (
    <div className="app-container">
      <header className="app-header">
        <h1 className="app-title">家計簿支出ダッシュボード</h1>
        <p className="app-subtitle">
          支出の内訳を円グラフで可視化。グラフやリストをクリックして詳細を確認できます。
        </p>
      </header>

      <section className="total-banner">
        <span className="total-label">今月の支出合計</span>
        <span className="total-value">¥{totalAmount.toLocaleString()}</span>
      </section>

      <main className="dashboard-grid">
        <ExpensePieChart
          items={items}
          selectedId={selectedId}
          onSelect={handleSelectItem}
        />
        <ExpenseList
          items={items}
          selectedId={selectedId}
          onSelect={(id) => handleSelectItem(id === selectedId ? null : id)}
          onDelete={handleDeleteItem}
          totalAmount={totalAmount}
        />
      </main>

      <section className="form-card">
        <h2 className="form-title">支出を追加</h2>
        <form className="expense-form" onSubmit={handleAddExpense}>
          <div className="form-row">
            <div className="form-group">
              <label className="form-label" htmlFor="expense-category">
                カテゴリー
              </label>
              <select
                id="expense-category"
                className="form-select"
                value={category}
                onChange={(e) => setCategory(e.target.value)}
              >
                {PRESET_CATEGORIES.map((preset) => (
                  <option key={preset.category} value={preset.category}>
                    {preset.category}
                  </option>
                ))}
              </select>
            </div>

            <div className="form-group">
              <label className="form-label" htmlFor="expense-amount">
                金額 (円)
              </label>
              <input
                id="expense-amount"
                type="number"
                min="1"
                step="1"
                placeholder="例: 5000"
                className="form-input"
                value={amountInput}
                onChange={(e) => {
                  setAmountInput(e.target.value);
                  if (errorMessage) {
                    setErrorMessage('');
                  }
                }}
                required
              />
            </div>

            <div className="form-group">
              <label className="form-label" htmlFor="expense-note">
                メモ
              </label>
              <input
                id="expense-note"
                type="text"
                placeholder="例: スーパーでの買い物"
                className="form-input"
                value={note}
                onChange={(e) => setNote(e.target.value)}
              />
            </div>
          </div>

          {errorMessage && (
            <p role="alert" className="form-error-message">
              {errorMessage}
            </p>
          )}

          <button type="submit" className="btn-add">
            <span>+</span> 支出を登録する
          </button>
        </form>
      </section>
    </div>
  );
};

export default App;
